import {bindPersistence} from './persistence.js';
import {projectPlan,effectiveWorth,BUDGET_LINKS} from './planning.js';
import {planningControls,planningSummary,restrictedControl} from './planning-view.js';
import {paymentChart,homeComparison,contributionChart} from './charts.js';
import {BENCHMARK_NOTES} from './benchmarks.js';
import {budgetView,budgetResults,budgetChart,summaryTemplate} from './budget-view.js';
import {targetFit,inputOrigin,markEntered} from './presentation.js';
import {budgetSummary,ANNUAL_ELIGIBLE,reviewSummary} from './budget.js';
import {newState,validateState,validateHome,homeLimits,applyStress,affordability,requiredIncome,netWorth,projectWorth,benchmark,GROUPS,ASSET_GROUPS,rowTotal,projectionYears} from './model.js';
import {HELP,SOURCES,LABELS,FIELD_HELP} from './content.js';
import {formatMoneyInputs,numericInputValue,validNumericInput} from './numbers.js';
import {taxControls} from './release-view.js';
import {bindReleaseUI} from './release-actions.js';


let state=newState(),invalid=new Set(),toastTimer,helpTimer;
const budgetUI={chart:'bars',get housing(){return state.budget.housing||'current'},set housing(value){state.budget.housing=value}};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'No finite limit':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const compact=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(n);
const pct=n=>n===null?'—':`${n.toFixed(1)}%`;
function notice(msg){$('#status').textContent=msg;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#status').textContent='',4500)}
const help=(key)=>`<button type="button" class="help" data-help="${key}" aria-label="Explain ${esc(HELP[key]?.[0]??key)}" aria-haspopup="dialog">?</button>`;
const originLabel=origin=>({example:'Example · editable',entered:'Your entry',imported:'Imported entry',saved:'Saved value'})[origin];
function field(key){const annual=state.mode==='budget'&&state.budget.annualFields.includes(key),v=state.home[key]*(annual?12:1),[min,baseMax]=homeLimits(key),max=baseMax*(annual?12:1),percent=['downPaymentPct','closingCostPct','interestRate','propertyTaxRate','maintenancePct','pmiRate','incomeTaxRate','payrollTaxRate','stateTaxRate','secondEarnerPct'].includes(key),years=key==='age'||key==='loanTermYears',origin=inputOrigin(state,'home',key);
 return `<div class="field"><div class="field-label"><label for="h-${key}">${LABELS[key]}</label>${FIELD_HELP[key]?help(FIELD_HELP[key]):''}</div><div class="input-wrap">${!percent&&!years?'<span>$</span>':''}<input class="${origin==='example'?'example-value':''}" type="number" inputmode="decimal" id="h-${key}" data-home="${key}" value="${v}" aria-describedby="origin-${key}" min="${min}" max="${max}" step="${years?1:'any'}">${percent?'<span>%</span>':years?'<span>years</span>':''}</div><small id="origin-${key}" class="entry-origin">${originLabel(origin)}</small>${state.mode==='budget'&&ANNUAL_ELIGIBLE.includes(key)?`<select class="period-select" data-period="${key}" aria-label="Entry period for ${LABELS[key]}"><option value="monthly" ${annual?'':'selected'}>Monthly</option><option value="annual" ${annual?'selected':''}>Annual ÷ 12</option></select>`:''}</div>`;
}
const fields=keys=>`<div class="fields">${keys.map(field).join('')}</div>`;
function section(id,title,subtitle,body,open=false){return `<details class="panel fold" id="section-${id}" ${open?'open':''}><summary><span class="section-number">${id}</span><span class="section-heading"><strong>${title}</strong><small>${subtitle}</small></span><span class="section-total" data-total="${id}"></span><span class="chevron" aria-hidden="true">⌄</span></summary><div class="fold-body">${body}</div></details>`}
const miniNote=text=>`<p class="inline-note">${text}</p>`;
const row=(label,value,cls='')=>`<div class="result-row ${cls}"><span>${label}</span><strong>${value}</strong></div>`;
const lightRow=(label,value)=>`<div class="light-row"><span>${label}</span><strong>${value}</strong></div>`;
const title=(eyebrow,heading,sub)=>`<div class="page-title"><div><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1><p>${sub}</p></div><span class="unit-note">USD · household figures</span></div>`;
function render(){hideHover();invalid.clear();closeCoach();
 $$('.tab').forEach(b=>{const active=b.dataset.mode===state.mode;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1});
 $('#calculator').setAttribute('aria-labelledby',`tab-${state.mode}`);
 $('#calculator').dataset.view=state.mode;
 $('.sample-label').textContent=state.mode==='worth'?'Enter current balances · count each asset once':'Gray = example · dark = entered or saved · ? explains each';
 if(state.mode==='worth')renderWorth();else if(state.mode==='budget')$('#calculator').innerHTML=budgetView(state,{title,section,fields,help,miniNote,taxControls:()=>taxControls(state,{fields,help})});else renderHome();formatMoneyInputs();renderResults();
}
function renderHome(){const backward=state.mode==='backward';
 $('#calculator').innerHTML=title(backward?'HOME AFFORDABILITY':'LIFESTYLE & INCOME',backward?'A home that fits your life.':'What does your life cost?',backward?'Start with your income. Leave room for everything else.':'Build the monthly plan. See the income it would take.')+
 `<div class="workspace-grid home-layout"><div id="input-panels"><section class="panel home-basics"><h2>${backward?'Start with the basics':'Your desired lifestyle'}</h2>${fields(backward?['householdGrossAnnual','availableCash','homePrice','monthlyBuffer']:['homePrice','availableCash','monthlyBuffer','householdGrossAnnual'])}${miniNote('Expenses below already count, even when collapsed. Review the examples to make this your plan.')}</section><div class="home-details"><details class="panel fold household-details" id="household-details"><summary><span class="section-heading"><strong>Household expenses & savings</strong><small>Already included · expand to edit every category</small></span><span class="section-total" id="household-total"></span><span class="chevron" aria-hidden="true">⌄</span></summary><div class="fold-body">`+
 section('03','Household & lifestyle','Groceries, childcare, travel, and daily life',fields(GROUPS.lifestyle))+
 section('04','Vehicles & other debts','Monthly payments and running costs',fields([...GROUPS.vehicles,'otherDebtPayment'])+miniNote('Other debt payments can include student loans, personal loans, or credit-card repayments. Avoid counting the same purchase as both spending and debt repayment.'))+
 section('05','Healthcare & protection','Premiums, out-of-pocket costs, insurance',fields([...GROUPS.healthcare,...GROUPS.protection])+miniNote('Include employee-paid premiums even if they come from your paycheck; this simplified tax model does not separately model pre-tax health benefits.'))+
 section('06','Savings & retirement','Monthly contributions, not account balances',fields([...GROUPS.savings,'pre401k'])+miniNote('These contributions fund your future, but reduce the amount available for a house today. Account balances belong in Net worth.'))+
 `<button class="text-btn" data-mode="budget">See this household in Budget →</button></div></details>`+
 section('02','Loan & ownership assumptions','Down payment, rates, insurance & cash reserve',fields(['downPaymentPct','loanTermYears','interestRate','propertyTaxRate','homeInsurance','hoa','utilities','maintenancePct','pmiRate','closingCostPct','cashReserve'])+miniNote('Your starting cash includes the reserve kept untouched. The rest must cover the down payment and closing costs. Rates and local costs are editable; no location lookup is applied.')+'<button class="btn" id="ownership-quotes">Use annual tax & insurance quotes</button>')+
 section('07','Taxes & household details','Choose a tax estimate and household age',taxControls(state,{fields,help})+fields(['age']))+
 `<details class="panel fold"><summary><span class="section-heading"><strong>Stress test</strong><small>Try higher borrowing and living costs</small></span><span class="chevron" aria-hidden="true">⌄</span></summary><div class="fold-body"><div class="stress-heading"><h2>Enable stress test ${help('stress')}</h2><label class="switch"><input type="checkbox" id="stress-enabled" ${state.stress.enabled?'checked':''} aria-label="Enable stress test"><span></span></label></div><div id="stress-fields" ${state.stress.enabled?'':'hidden'}>${stressFields()}</div></div></details></div></div><aside id="results"></aside></div>`;
}
function stressFields(){return `<div class="fields">${[['rateAdj','Mortgage rate change','points',-20,20],['lifestylePct','Lifestyle cost change','%',-90,200],['healthcarePct','Healthcare cost change','%',-90,200],['propTaxBump','Property tax change','points',-20,20]].map(([key,label,unit,min,max])=>`<div class="field"><label for="s-${key}">${label}</label><div class="input-wrap"><input id="s-${key}" type="number" data-stress="${key}" min="${min}" max="${max}" step="any" value="${state.stress[key]}"><span>${unit}</span></div></div>`).join('')}</div><p class="inline-note">The results use adjusted inputs. Turn this off to return to your base plan.</p>`}
const GROUP_LABELS={cash:'Cash & savings',investments:'Investments & retirement',property:'Home & real estate',vehicles:'Vehicles',belongings:'Material belongings',other:'Business & other assets',debts:'What you owe'};
function accountHelp(group,r){if(group==='vehicles')return 'depreciation';if(group==='belongings')return 'belongings';if(group==='debts')return 'debt';if(r.id==='401k')return 'k401';if(r.id==='roth')return 'roth';if(r.id==='hsa')return 'hsa';if(r.id==='529')return 'college';if(r.id==='brokerage')return 'brokerage';if(r.id==='emergency')return 'emergency';return group==='property'?'netWorth':'return'}
function accountRow(group,r){const future=state.worthView==='future',isDebt=group==='debts',depreciating=group==='vehicles'||group==='belongings';
 const linked=state.planning.useBudgetSavings&&BUDGET_LINKS.some(([g,id])=>g===group&&id===r.id);
 const shown=linked?effectiveWorth(state)[group].find(x=>x.id===r.id):r;
 const numeric=(key,label,unit,min,max,hkey)=>`<div class="field"><div class="field-label"><label for="w-${group}-${r.id}-${key}">${label}</label>${hkey?help(hkey):''}</div><div class="input-wrap">${unit==='$'?'<span>$</span>':''}<input type="number" inputmode="decimal" id="w-${group}-${r.id}-${key}" data-group="${group}" data-row="${r.id}" data-prop="${key}" value="${shown[key]}" ${linked&&key==='monthly'?'disabled aria-label="Monthly addition linked from Budget"':''} min="${min}" max="${max}" step="any">${unit==='$'?'':`<span>${unit}</span>`}</div></div>`;
 return `<div class="account-row"><div class="account-top"><label class="sr-only" for="name-${group}-${r.id}">Name of ${GROUP_LABELS[group].toLowerCase()} entry</label><input class="account-name" id="name-${group}-${r.id}" data-group="${group}" data-row="${r.id}" data-prop="name" value="${esc(r.name)}" maxlength="100">${help(accountHelp(group,r))}<button type="button" class="remove-row" data-remove="${group}" data-id="${r.id}" aria-label="Remove ${esc(r.name)}">−</button></div><div class="account-fields ${future?'forecast-fields':''}">`+
 numeric('value',isDebt?'Remaining balance':'Current value','$',0,1e12,isDebt?'debt':depreciating?'resale':null)+
 (future?numeric('rate',isDebt?'Annual interest rate':depreciating?'Depreciation / year':'Growth / year','%',isDebt||depreciating?0:-99,isDebt?60:100,isDebt?'apr':depreciating?group==='vehicles'?'depreciation':'belongings':'return'):'')+
 (future&&isDebt?numeric('payment','Payment / month','$',0,1e9,'apr'):future&&['cash','investments'].includes(group)?numeric('monthly','Add / month','$',0,1e9,'contributions'):'')+`</div>${future&&linked?'<p class="inline-note">Monthly addition linked from Budget. Turn off the link to edit a separate assumption.</p>':''}${future?restrictedControl(r,group):''}</div>`;
}
function accountSection(group,index,open=false){const hints={cash:'Exclude balances listed again elsewhere.',investments:'Include only your household’s vested account balances.',property:'Full current property value. Put mortgage balances under What you owe.',vehicles:'Resale value, not purchase price. Auto loans go under What you owe.',belongings:'Computers, furniture, jewelry, cameras, instruments, or tools.',other:'Your share of a business, collectibles, or other assets. Exclude assets already counted.',debts:'Mortgages, auto loans, credit cards, student loans, personal loans, or unpaid taxes.'};
 return section(index,GROUP_LABELS[group],hints[group],`<div id="rows-${group}">${state.worth[group].map(r=>accountRow(group,r)).join('')}</div><button class="btn add-row" data-add="${group}"><span aria-hidden="true">+</span> Add ${group==='vehicles'?'vehicle':group==='belongings'?'belonging':group==='debts'?'debt':'account / asset'}</button>`,open);
}
function refreshProjectionAge(){
 const age=state.home.age,target=age+state.worth.years,maxAge=Math.min(120,age+100);
 for(const id of ['p-targetAge','age-range']){const el=$('#'+id);el.min=age+1;el.max=maxAge;if(!invalid.has(id))el.value=target;}
 $('#age-heading').textContent=target;$('#horizon-label').textContent=`${state.worth.years} years from now`;
 $('.range-labels>span:first-child').textContent=`Age ${age+1}`;$('.range-labels>span:last-child').textContent=`Age ${maxAge}`;
 $('.age-presets').innerHTML=[age+10,65,85].filter((a,i,all)=>a>age&&a<=maxAge&&all.indexOf(a)===i).map(a=>`<button class="btn" data-target-age="${a}">${a===age+10?'+10 years':'Age '+a}</button>`).join('');
}
function futureFields(){
 const w=state.worth,age=state.home.age,target=age+w.years,maxAge=Math.min(120,age+100);
 const presets=[age+10,65,85].filter((a,i,all)=>a>age&&a<=maxAge&&all.indexOf(a)===i);
 const options=[['inflation','Annual inflation','%',0,30,'inflation'],['stopAge','Stop new contributions at age','years',18,120,'contributions'],['withdrawalAge','Start withdrawals at age','years',18,120,'withdrawal'],['withdrawalMonthly','Withdraw each month','$',0,1e9,'withdrawal']];
 return `<section class="panel projection-controls"><div class="projection-top"><div><p class="eyebrow">LOOK AHEAD</p><h2>Your finances at age <span id="age-heading">${target}</span> ${help('compound')}</h2></div><div class="year-box"><label for="p-targetAge">Target age</label><input id="p-targetAge" type="number" min="${age+1}" max="${maxAge}" step="1" data-projection="targetAge" value="${target}"></div></div><input id="age-range" aria-label="Age to project to" type="range" min="${age+1}" max="${maxAge}" value="${target}"><div class="range-labels"><span>Age ${age+1}</span><strong id="horizon-label">${w.years} years from now</strong><span>Age ${maxAge}</span></div><div class="age-presets">${presets.map(a=>`<button class="btn" data-target-age="${a}">${a===age+10?'+10 years':'Age '+a}</button>`).join('')}</div>${planningControls(state)}<details class="projection-assumptions"><summary>Withdrawal & inflation assumptions</summary><div class="fields">${options.map(([key,label,unit,min,max,hkey])=>`<div class="field"><div class="field-label"><label for="p-${key}">${label}</label>${help(hkey)}</div><div class="input-wrap">${unit==='$'?'<span>$</span>':''}<input type="number" id="p-${key}" data-projection="${key}" min="${min}" max="${max}" step="${unit==='years'?1:'any'}" value="${w[key]}">${unit==='$'?'':`<span>${unit}</span>`}</div></div>`).join('')}</div><p class="inline-note">Edit each account’s growth and monthly additions below. Future contributions and debt payments are assumed funded from future income; they are not deducted from your listed cash balances. This does not automatically purchase the home in your affordability plan. Longer horizons magnify small changes in assumptions.</p></details></section>`;
}
function renderWorth(){const future=state.worthView==='future';$('#calculator').innerHTML=title('NET WORTH',future?'Make room for your future.':'Everything you own. Less what you owe.',future?'Explore compound growth, saving, debt, and depreciation.':'A clearer picture starts with your balances today.')+
 `<div class="worth-tabs" role="tablist" aria-label="Net worth time frame"><button class="worth-tab ${future?'':'active'}" id="worth-today" role="tab" aria-selected="${!future}" aria-controls="worth-panel" tabindex="${future?-1:0}" data-worth-view="today"><strong>Net worth today</strong><span>Your current financial snapshot</span></button><button class="worth-tab ${future?'active':''}" id="worth-future" role="tab" aria-selected="${future}" aria-controls="worth-panel" tabindex="${future?0:-1}" data-worth-view="future"><strong>Estimated future net worth <span aria-hidden="true">↗</span></strong><span>Choose a future age & explore the possibilities</span></button></div><div id="worth-panel" role="tabpanel" aria-labelledby="worth-${state.worthView}"><div class="workspace-grid"><div id="input-panels"><section class="panel"><div class="fields">${field('age')}<div class="networth-intro">${help('netWorth')}<strong>Assets − debts = net worth</strong><p>Enter current values, not monthly income. Blank balances start at $0.</p></div></div></section>${future?futureFields():''}${[...ASSET_GROUPS,'debts'].map((g,i)=>accountSection(g,String(i+1).padStart(2,'0'),i===0)).join('')}</div><aside id="results"></aside></div></div>`;}
function setTargetAge(age){state.worth.years=projectionYears(state.home.age,age);const input=$('#p-targetAge');input.value=age;input.setAttribute('aria-invalid','false');invalid.delete('p-targetAge');$('#age-range').value=age;$('#age-heading').textContent=age;$('#horizon-label').textContent=`${state.worth.years} years from now`;closeCoach();renderResults()}
function issues(){return [...invalid].length?['Please correct the highlighted number fields.']:validateHome(state.home).map(e=>{for(const [k,label]of Object.entries(LABELS))e=e.replace(k,label);return e})}
function renderResults(){const errors=issues();$('#ask-dave').disabled=errors.length>0;if(errors.length){if(state.mode==='budget')$('#budget-chart').textContent='Correct the highlighted inputs to see your allocation.';$('#results').innerHTML=`<section class="panel error-panel" role="alert"><h2>Check these inputs</h2><ul>${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul><p>Results will return once the entries are valid.</p></section>`;return}
 if(state.mode==='worth')renderWorthResults();else if(state.mode==='budget'){const focusId=document.activeElement?.id;$('#results').innerHTML=budgetResults(state,{money,row,lightRow},budgetUI);$('#budget-chart').innerHTML=budgetChart(state,{money},budgetUI);if(focusId)document.getElementById(focusId)?.focus();const b=budgetSummary(state.home,state.budget);for(const [id,v]of Object.entries({'01':b.takeHome,'02':b.currentHousing,'03':b.essential,'04':b.flexible,'05':b.debt,'06':b.savings})){const el=$(`[data-total="${id}"]`);if(el)el.textContent=money(v)+'/mo'}}else renderHomeResults();}
function homeMeter(a,f){const fit=targetFit(a,f.monthlyBuffer,f.homePrice);return `<section class="target-meter" aria-label="Monthly fit of your target home"><div class="card-top"><h2>Your ${money(f.homePrice)} target</h2>${help('planMeter')}</div><div class="affordability-gauge" role="img" aria-label="${fit.label}">${fit.position===null?'':`<span class="gauge-marker" style="left:${fit.position}%" aria-hidden="true"></span>`}</div><div class="gauge-labels" aria-hidden="true"><span>Over budget</span><span>Below buffer</span><span>Buffer met</span></div><p class="meter-verdict ${fit.kind}">${fit.label}</p>${fit.kind==='unset'?'':lightRow('Money left after the target home',money(a.bufferAtTarget))+lightRow('Your chosen monthly buffer',money(f.monthlyBuffer))}${fit.monthlyGap>.01?`<p class="inline-note">Needs ${money(fit.monthlyGap)} more each month to preserve your buffer.</p>`:''}<p class="cash-check ${fit.cashGap>.01?'shortfall':''}">${fit.kind==='unset'?'Choose a target to check upfront cash.':fit.cashGap>.01?`Upfront cash: ${money(fit.cashGap)} short, including your reserve.`:'Upfront cash covers this target and your reserve.'}</p><p class="inline-note">Monthly planning check, not loan approval. ${state.stress.enabled?'Stress adjustments are included.':''}</p></section>`}
function renderHomeResults(){const f=applyStress(state.home,state.stress),a=affordability(f),r=requiredIncome(f),backward=state.mode==='backward',base=state.stress.enabled?affordability(state.home):null;
 const cost=backward?a.maximum:r.home,groups=a.groups, cashLimited=a.limitedBy==='cash';
 const heading=backward?'ESTIMATED HOME BUDGET':'GROSS INCOME NEEDED / YEAR';
 const main=backward?a.maxHome:r.annual;
 const breakdown=[['Principal & interest',cost.pi],['Property tax',cost.tax],['Homeowners insurance',cost.insurance],['HOA',cost.hoa],['PMI',cost.pmi],['Maintenance reserve',cost.maintenance],['Utilities',cost.utilities]];
 const targetOkay=a.cashGap<.01&&a.bufferAtTarget>=f.monthlyBuffer-.01;
 $('#results').innerHTML=`<section class="result-card">${state.stress.enabled?'<span class="badge">Stress test on</span>':''}<p class="eyebrow">${heading}</p>${backward&&a.maxHome===0?(a.budgetLimit===0?'<p class="empty-home-message">Your current spending plan leaves no room for a home purchase.</p><p class="empty-home-aside">Looks like you&#39;re <strong class="renting-accent">renting</strong> pal !</p>':'<p class="empty-home-message">Your available cash does not cover the purchase costs and reserve.</p>'):'<div class="big-number">'+money(main)+'</div>'}<p class="result-sub">${backward?(a.maxHome===null?'Add ownership costs or an upfront cash constraint to get a finite limit.':cashLimited?'Your upfront cash sets the limit.':'Your monthly spending plan sets the limit.'):money(r.gross)+' per month, before taxes and deductions'}</p><div class="result-rule"></div>${backward?(a.maxHome===0?row('Monthly housing budget after your buffer',money(a.housingBudget))+row('Fixed ownership assumptions / month',money(f.homeInsurance+f.hoa+f.utilities))+row('Cash available after chosen reserve',money(f.availableCash-f.cashReserve)):row('All-in ownership / month',money(cost.total))+row('Housing budget after savings',money(a.housingBudget))+row('Cash needed, including reserve',money(cost.cashRequired))+row('Breathing room at this price',money(a.takeHome-a.nonHousing-cost.total))):row('Housing & ownership',money(cost.total))+row('Living costs & other debts',money(a.nonHousing-groups.savings))+row('After-tax savings',money(groups.savings))+row('Pre-tax retirement',money(f.pre401k))+row('Estimated taxes',money(r.taxes))+row('Monthly breathing room',money(f.monthlyBuffer))}
 ${state.stress.enabled?`<div class="baseline">Without stress: ${backward?money(base.maxHome):money(requiredIncome(state.home).annual)+' / year'}</div>`:''}</section>
 ${homeMeter(a,f)}<button class="btn compare-homes" id="compare-homes">Compare home prices</button>
 <details class="panel target-card result-details"><summary>Target purchase costs & debt ratio</summary><div class="card-top"><span class="pill ${targetOkay?'ok':'caution'}">${targetOkay?'Fits this plan':'Needs a closer look'}</span></div>${lightRow('All-in housing / month',money(a.target.total))}${lightRow('Cash needed incl. reserve',money(a.target.cashRequired))}${lightRow('Down payment',money(a.target.down))}${lightRow('Closing costs',money(a.target.closing))}${lightRow('Cash kept untouched',money(f.cashReserve))}${lightRow('Cash shortfall',money(a.cashGap))}${lightRow('Monthly money left over',money(a.bufferAtTarget))}${lightRow(`Debt-to-income ${help('dti')}`,pct(a.dti))}<p class="inline-note">${targetOkay?'Includes your selected monthly buffer.':'The target must fit both your monthly plan and your cash after reserves.'} This is not a loan approval.</p></details>
 <details class="panel breakdown result-details"><summary>Ownership breakdown & calculation</summary><p class="section-caption">Monthly ownership at ${backward?'your estimated maximum':'your desired price'}</p>${paymentChart(cost)}${breakdown.map(([name,v])=>lightRow(name,money(v))).join('')}<div class="total-line">${lightRow('Total housing',money(cost.total))}</div><details class="calculation-details"><summary>Follow the income calculation</summary>${lightRow('Gross income / month',money(backward?a.gross:r.gross))}${lightRow('Less pre-tax retirement',money(f.pre401k))}${lightRow('Less estimated taxes',money(backward?a.taxes:r.taxes))}${lightRow('After-tax money',money(backward?a.takeHome:r.gross-r.taxes-f.pre401k))}${lightRow('Less non-housing costs & savings',money(a.nonHousing))}${lightRow('Less chosen buffer',money(f.monthlyBuffer))}</details></details>
 <div class="note">Rates and costs are examples, not live quotes. ${help('mortgage')} ${help('takeHome')} ${f.taxMode===1?'Tax results use the simplified 2026 wage-tax model.':'Tax results use your editable effective rates.'} Neither mode is a full tax return.</div>`;
 const totals={'01':a.gross,'03':groups.lifestyle,'04':groups.vehicles+f.otherDebtPayment,'05':groups.healthcare+groups.protection,'06':groups.savings+f.pre401k,'07':a.taxes};
 for(const [id,value]of Object.entries(totals)){const el=$(`[data-total="${id}"]`);if(el)el.textContent=money(value)+'/mo'}
 $('#household-total').textContent=money(a.nonHousing+f.pre401k)+'/mo';
}
function renderWorthResults(){const w=state.worth,n=netWorth(w),b=benchmark(state.home.age),future=state.worthView==='future',p=future?projectPlan(state):null;
 const empty=n.assets===0&&n.liabilities===0;
 $('#results').innerHTML=`<section class="result-card"><p class="eyebrow">${future?'PROJECTED NET WORTH · AGE '+(state.home.age+w.years):'YOUR NET WORTH TODAY'} ${help(future?'compound':'netWorth')}</p><div class="big-number">${money(future?p.end.total:n.total)}</div><p class="result-sub">${future?`${w.years} years from now · an illustrative scenario`:empty?'Your snapshot starts with the balances you enter.':'Current assets minus outstanding debts'}</p>${future?contributionChart(p,state.home.age):'<div class="asset-equation"><div><span>ASSETS</span><strong>'+money(n.assets)+'</strong></div><b>−</b><div><span>DEBTS</span><strong>'+money(n.liabilities)+'</strong></div></div>'}${future?row('In today’s purchasing power',money(p.end.real))+row('Net worth today',money(n.total))+row('Future assets',money(p.end.assets))+row('Future debts',money(p.end.liabilities))+row('New savings contributed',money(p.end.added))+row('Portfolio withdrawals funded',money(p.end.withdrawn)):''}</section>
 ${future?planningSummary(state,p):''}
 ${future&&w.years>40?'<div class="notice-box">A '+w.years+'-year view is a mathematical scenario. Fixed rates, unchanged assets, and spending assumptions become much less realistic over very long horizons.</div>':''}
 ${future&&p.end.unfunded>0?`<div class="notice-box danger">${money(p.end.unfunded)} of requested withdrawals could not be funded from cash and investments. Property and belongings are not automatically sold.</div>`:''}
 ${future&&p.negativeAmortization.length?`<div class="notice-box danger">Payments may not reduce these balances: ${p.negativeAmortization.map(esc).join(', ')}. Check each contractual interest rate and monthly payment.</div>`:''}
 <section class="panel breakdown"><h2>${future?'Your starting assets':'Your balance sheet'}</h2>${ASSET_GROUPS.map(g=>lightRow(GROUP_LABELS[g],money(n.groups[g]))).join('')}<div class="total-line">${lightRow('Total assets',money(n.assets))}${lightRow('Total debts','− '+money(n.liabilities))}</div>${lightRow('Net worth',money(n.total))}</section>
 <section class="panel context-card"><p class="eyebrow">CONTEXT, NOT A SCORE</p><h2>Households at age ${b.label} ${help('benchmark')}</h2>${lightRow('Historical median net worth',money(b.worth))}${lightRow('Historical median annual income',money(b.income))}<p class="inline-note">2022 Survey of Consumer Finances. Values are in 2022 dollars; income is for the preceding year. This is not a current-dollar target. Your situation and assets counted may differ.</p><a href="${SOURCES.fed.url}" target="_blank" rel="noopener noreferrer">Read the Federal Reserve data ↗</a></section>
 ${future?`<section class="panel"><h2>Forecast assumptions</h2><p class="inline-note">Before future withdrawal taxes and selling costs. Planned additions stop at age ${w.stopAge}; withdrawals start at ${w.withdrawalAge}. Income assumptions check contribution funding; they do not become assets automatically. No inheritance, pension, Social Security, or home purchase is added automatically.</p></section>`:'<div class="note">Retirement balances are shown before withdrawal taxes. Avoid counting an emergency fund twice or adding both a property’s full value and its equity.</div>'}`;
 [...ASSET_GROUPS,'debts'].forEach((g,i)=>{const el=$(`[data-total="${String(i+1).padStart(2,'0')}"]`);if(el)el.textContent=money(rowTotal(w[g]))});
}
function readScenarios(){let data;try{data=JSON.parse(localStorage.getItem('life-ledger:scenarios:v1')||'[]')}catch{throw new Error('Saved scenarios could not be read in this browser.')}if(!Array.isArray(data))throw new Error('Saved scenarios have an invalid format.');return data.filter(x=>x&&typeof x.name==='string'&&typeof x.savedAt==='string').slice(0,100)}
function writeScenarios(list){try{localStorage.setItem('life-ledger:scenarios:v1',JSON.stringify(list))}catch{throw new Error('This browser could not save the scenario. Storage may be full or disabled.')}}
function dialog(title,content,after){hideHover();const root=$('#overlay-root');root.innerHTML=`<dialog class="modal" aria-labelledby="dialog-heading"><div class="modal-head"><h2 id="dialog-heading">${title}</h2><button class="close-btn" data-close aria-label="Close dialog">×</button></div><div class="modal-body">${content}</div></dialog>`;const d=root.querySelector('dialog');const previous=document.activeElement;d.addEventListener('close',()=>{root.innerHTML='';previous?.focus()},{once:true});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.showModal();after?.(d)}
function saveScenario(){if(issues().length){notice('Correct the inputs before saving.');return}const name=$('#scenario-name').value.trim();if(!name){$('#scenario-name').focus();notice('Give this scenario a name first.');return}try{validateState(state);const list=readScenarios(),index=list.findIndex(x=>x.name===name);const commit=()=>{if(index<0&&list.length>=100)throw new Error('You have 100 saved scenarios. Delete one or replace an existing name first.');const item={name,savedAt:new Date().toISOString(),state:structuredClone(state)};if(index>=0)list[index]=item;else list.push(item);writeScenarios(list);notice(`Saved “${name}” on this device.`)};if(index>=0)dialog('Replace saved scenario?',`<p>Replace “${esc(name)}” with your current inputs?</p><div class="dialog-actions"><button class="btn" data-close>Cancel</button><button class="btn dark" id="confirm-save">Replace</button></div>`,d=>$('#confirm-save').onclick=()=>{try{commit();d.close()}catch(e){notice(e.message)}});else commit()}catch(e){notice(e.message)}}
function showSaved(){try{const list=readScenarios();dialog('Saved scenarios',`${miniNote('Stored only in this browser on this device. Loading replaces the currently displayed inputs. Save your current work first if needed.')}<div class="saved-list">${list.length?list.map((s,i)=>`<div class="saved-item"><button class="saved-load" data-load-index="${i}"><strong>${esc(s.name)}</strong><small>${esc(new Date(s.savedAt).toLocaleDateString())}</small></button><button class="btn remove-scenario" data-delete-index="${i}" aria-label="Delete ${esc(s.name)}">Delete</button></div>`).join(''):'<p>No saved scenarios yet. Name your current plan and select Save.</p>'}</div>`)}catch(e){notice(e.message)}}
function helpContent(key){if(['planMeter','wageTax','stateTax','earnerShare'].includes(key))return '<p>'+esc(HELP[key][1])+'</p>';const [name,body,source]=HELP[key],b=BENCHMARK_NOTES[key],s=b?.source||source;return `<p>${esc(body)}</p>${s?`<a href="${SOURCES[s].url}" target="_blank" rel="noopener noreferrer">${SOURCES[s].label} ↗</a>`:''}<p class="help-benchmark">${b?`${esc(b.lead)} <strong>${esc(b.value)}</strong> — ${esc(b.tail)}`:'Use the definition above to choose a figure for your plan. No numeric benchmark is used for this explanation.'}</p>`}
function hideHover(){clearTimeout(helpTimer);$('#hover-help')?.remove()}
function showHover(button){const key=button.dataset.help;if(!HELP[key]||$('dialog[open]'))return;hideHover();const pop=document.createElement('aside');pop.id='hover-help';pop.className='help-popover';pop.setAttribute('role','tooltip');pop.innerHTML=`<strong>${HELP[key][0]}</strong>${helpContent(key)}`;document.body.append(pop);const r=button.getBoundingClientRect();pop.style.left=Math.max(12,Math.min(r.left,window.innerWidth-pop.offsetWidth-12))+'px';const h=pop.offsetHeight;pop.style.top=Math.max(12,Math.min(r.bottom+10,window.innerHeight-h-12))+'px';pop.addEventListener('mouseenter',()=>clearTimeout(helpTimer));pop.addEventListener('mouseleave',hideHover)}
function closeCoach(){release.closeCoach()}
function askDave(){release.askDave()}
function methodology(){dialog('Assumptions & sources',`<h3>A household planning tool</h3><p>Values are in U.S. dollars. Income, home price, down payment, and current rent use dated published medians. The mortgage rate is a dated average. Other starting amounts and rates are editable planning assumptions; a benchmark is not a recommendation. Different populations and years do not form one statistically typical household. The net-worth worksheet begins at zero. Your entries are calculated in this browser; named saves use device-local browser storage. This app makes no account connections and sends no financial form entries to a backend. Hosting providers may still process ordinary website traffic.</p><h3>Home affordability</h3><p>Monthly housing includes mortgage principal and interest, property tax, insurance, HOA, modeled PMI, maintenance, and utilities. Available cash must cover the down payment, estimated closing costs, and your untouched reserve. The maximum is the lower of the monthly-budget limit and the cash limit. It is not a lender qualification or recommendation to spend the maximum.</p><h3>Two tax estimates</h3><p>Effective-rate mode applies your income-tax rate after pre-tax retirement and payroll rate to gross pay. Optional 2026 wage-tax mode uses federal progressive brackets, the filing-status standard deduction, per-earner Social Security caps, Medicare and Additional Medicare, plus your state/local effective-rate assumption. Required income solves that same selected model. Wages only: no credits, itemized or additional deductions, non-wage income, pre-tax health benefits or legal contribution-limit checks. This is a planning estimate, not a tax return.</p><h3>Net worth & projections</h3><p>Net worth = current assets − remaining debt. Annual returns are converted to equivalent monthly rates; additions arrive at month-end, stop at the selected age, and optionally follow Budget savings. Employer match is entered separately; do not include it again in personal additions. Optional growth assumptions apply annually. Debt interest is contractual annual interest rate ÷ 12, applied before fixed monthly payments. Payments stop at zero and are assumed funded externally. Withdrawals use eligible cash first, then eligible investments; HSA and 529 accounts are excluded by default from general spending. Optional inflation-adjusted withdrawals start with today’s dollar amount and grow from today. Unfunded amounts are reported. No automatic loan-payment reinvestment, replacement vehicles, future purchases, taxes on withdrawals, selling costs, or future benefits are included. Long horizons are mathematical scenarios, not predictions.</p><h3>Why Ask Dave reacts</h3><p>This animated character is an original parody, unaffiliated with Dave Ramsey or Ramsey Solutions. He checks the selected worksheet: monthly shortfalls, purchase cash, your buffer, car payments, debt-interest coverage, and forecast funding. Ranked findings explain amounts and link to editable inputs. An angry face means a priority in the entered plan, never a judgment about age or personal worth. Untouched examples receive an example review. Adjustable commentary thresholds and optional Ramsey preferences are kept separate from the calculator math. The 15% car-payment trigger is an app preference, not a Ramsey rule. No cloned voice, financial-data transmission, or external AI service is used.</p><h3>Budget & imports</h3><p>Budget shares income and spending with both home calculators. It replaces current all-in housing with proposed all-in housing. Pre-tax retirement is deducted once before take-home; insurance is counted once in expenses. Annual entries are divided by 12. Summary CSV imports are reviewed locally and replace only listed fields. No raw bank transaction auto-categorization or account connection is provided.</p><h3>Research references</h3><ul class="source-list">${Object.values(SOURCES).map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.label} ↗</a></li>`).join('')}</ul><p class="inline-note">Sources checked September 10–12, 2026. Federal Reserve figures are explicitly historical: 2022 survey, 2022 dollars. Vehicle default depreciation is an editable 10% midlife-car assumption; belongings use an illustrative 20%. Neither is a guaranteed valuation.</p>`)}
document.addEventListener('input',e=>{const el=e.target;if(!(el instanceof HTMLInputElement))return;
 if(el.id==='age-range'){setTargetAge(Number(el.value));return}
 if(!(el.dataset.home||el.dataset.stress||el.dataset.group||el.dataset.projection||el.dataset.budget))return;
 if(el.dataset.prop==='name'){const r=state.worth[el.dataset.group].find(r=>r.id===el.dataset.row);r.name=el.value;return}
 const v=numericInputValue(el);const valid=validNumericInput(el,v);
 el.setAttribute('aria-invalid',String(!valid));el.closest('.input-wrap')?.classList.toggle('invalid',!valid);
 if(!valid){invalid.add(el.id);renderResults();return}invalid.delete(el.id);
 if(el.dataset.home){markEntered(state,'home',el.dataset.home);el.classList.remove('example-value');const origin=$('#origin-'+el.dataset.home);if(origin)origin.textContent='Your entry';const target=state.home.age+state.worth.years;state.home[el.dataset.home]=v/(state.mode==='budget'&&state.budget.annualFields.includes(el.dataset.home)?12:1);if(el.dataset.home==='age'){state.worth.years=projectionYears(v,Math.min(120,v+100,Math.max(v+1,target)));if(state.mode==='worth'&&state.worthView==='future')refreshProjectionAge()}}
 else if(el.dataset.budget){state.budget[el.dataset.budget]=v;markEntered(state,'budget',el.dataset.budget);el.classList.remove('example-value');$('#origin-currentHousing').textContent='Your entry';}
 else if(el.dataset.stress)state.stress[el.dataset.stress]=v;
 else if(el.dataset.projection){if(el.dataset.projection==='targetAge'){setTargetAge(v);return}state.worth[el.dataset.projection]=v}
 else {const r=state.worth[el.dataset.group].find(r=>r.id===el.dataset.row);r[el.dataset.prop]=v}
 closeCoach();renderResults();
});
document.addEventListener('input',e=>{const el=e.target;if(!el.dataset.planning||el.type==='checkbox')return;const v=numericInputValue(el),valid=validNumericInput(el,v);el.setAttribute('aria-invalid',String(!valid));el.closest('.input-wrap')?.classList.toggle('invalid',!valid);if(!valid)invalid.add(el.id);else{invalid.delete(el.id);state.planning[el.dataset.planning]=v;}renderResults();});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.planning&&el.type==='checkbox'){state.planning[el.dataset.planning]=el.checked;if(el.dataset.planning==='useBudgetSavings'){if(invalid.size){state.planning.useBudgetSavings=!el.checked;el.checked=!el.checked;notice('Correct highlighted inputs before switching contribution sources.');return;}const opens=$$('details[id][open]').map(x=>x.id);render();for(const id of opens){const d=document.getElementById(id);if(d)d.open=true;}}else renderResults();}if(el.dataset.withdrawalAccount){const r=state.worth.investments.find(x=>x.id===el.dataset.withdrawalAccount);if(r)r.allowGeneralWithdrawals=el.checked;renderResults();}});
document.addEventListener('change',e=>{if(e.target.id==='stress-enabled'){state.stress.enabled=e.target.checked;$('#stress-fields').hidden=!state.stress.enabled;closeCoach();renderResults()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(invalid.size&&(b.dataset.mode||b.dataset.worthView||b.dataset.add||b.dataset.targetAge||b.dataset.loadIndex!==undefined)){notice('Correct the highlighted inputs before continuing.');return;}
 if(b.id==='compare-homes'){dialog('Compare home prices',homeComparison(applyStress(state.home,state.stress)))}
 else if(b.dataset.mode){state.mode=b.dataset.mode;render()}
 else if(b.dataset.budgetChart){budgetUI.chart=b.dataset.budgetChart;renderResults()}
 else if(b.dataset.budgetHousing){budgetUI.housing=b.dataset.budgetHousing;renderResults()}
 else if(b.dataset.targetAge){setTargetAge(Number(b.dataset.targetAge))}
 else if(b.dataset.worthView){state.worthView=b.dataset.worthView;render()}
 else if(b.dataset.help){dialog(HELP[b.dataset.help][0],helpContent(b.dataset.help))}
 else if(b.dataset.add){const group=b.dataset.add;if(state.worth[group].length>=50){notice('Up to 50 entries per category.');return}const id='entry-'+crypto.randomUUID();state.worth[group].push({id,name:group==='debts'?'New debt':group==='vehicles'?'Another vehicle':group==='belongings'?'Another belonging':'New account / asset',value:0,rate:group==='vehicles'?10:group==='belongings'?20:0,...(group==='debts'?{payment:0}:{monthly:0,accountType:group==='cash'?'cash':'other',allowGeneralWithdrawals:true})});$(`#rows-${group}`).insertAdjacentHTML('beforeend',accountRow(group,state.worth[group].at(-1)));formatMoneyInputs();$(`#name-${group}-${id}`).focus();renderResults()}
 else if(b.dataset.remove){const group=b.dataset.remove,id=b.dataset.id,r=state.worth[group].find(r=>r.id===id);const remove=()=>{closeCoach();state.worth[group]=state.worth[group].filter(r=>r.id!==id);b.closest('.account-row').remove();invalid=new Set([...invalid].filter(x=>!x.startsWith(`w-${group}-${id}-`)));formatMoneyInputs();renderResults();$(`[data-add="${group}"]`).focus()};if(r.value||r.monthly||r.payment)dialog('Remove this entry?',`<p>Remove “${esc(r.name)}” from this worksheet? Previously saved scenarios are unchanged.</p><div class="dialog-actions"><button class="btn" data-close>Cancel</button><button class="btn dark" id="confirm-remove">Remove</button></div>`,d=>$('#confirm-remove').onclick=()=>{remove();d.close()});else remove()}
 else if(b.dataset.loadIndex!==undefined){try{const s=readScenarios()[Number(b.dataset.loadIndex)];state=structuredClone(validateState(s.state));$('#scenario-name').value=s.name;$('dialog').close();render();notice(`Loaded “${s.name}”.`)}catch(err){notice(err.message)}}
 else if(b.dataset.deleteIndex!==undefined){const list=readScenarios(),i=Number(b.dataset.deleteIndex),name=list[i].name;dialog('Delete saved scenario?',`<p>Delete “${esc(name)}” from this browser?</p><div class="dialog-actions"><button class="btn" data-close>Cancel</button><button class="btn dark" id="confirm-delete">Delete</button></div>`,d=>$('#confirm-delete').onclick=()=>{try{list.splice(i,1);writeScenarios(list);d.close();showSaved()}catch(err){notice(err.message)}})}
 else if(b.hasAttribute('data-close'))$('dialog')?.close();else if(b.hasAttribute('data-close-coach'))closeCoach();else if(b.hasAttribute('data-method')||b.id==='methodology')methodology();
});
document.addEventListener('mouseover',e=>{const b=e.target.closest?.('[data-help]');if(b)showHover(b)});
document.addEventListener('mouseout',e=>{if(e.target.closest?.('[data-help]'))helpTimer=setTimeout(()=>{if(!$('#hover-help')?.matches(':hover'))hideHover()},160)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideHover();closeCoach()}const b=e.target.closest?.('[role="tab"]');if(!b)return;const tabs=[...b.parentElement.querySelectorAll('[role="tab"]')],i=tabs.indexOf(b);let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i-1+tabs.length)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();const id=tabs[next].id;tabs[next].click();$('#'+id)?.focus()}});
window.addEventListener('scroll',hideHover,{passive:true});window.addEventListener('resize',hideHover);
