$('#dave-sprite').style.backgroundImage='url(./dave-sprites.png)';$('#dave-sprite').style.display='block';
$('#dave-sprite').setAttribute('role','img');$('#dave-sprite').setAttribute('aria-label','Animated Dave Ramsey parody caricature');
