// Feature-detected, explicitly named actions. No network, account access, or hidden save.
export function registerTools(context){if(!context?.registerTool)return;const tools=[
 {name:'read_financial_plan',title:'Read displayed financial plan',description:'Read current worksheet inputs and calculated results from this browser only; contains user-entered financial data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters expected.');if(issues().length)throw new Error('The worksheet contains invalid inputs.');const h=applyStress(state.home,state.stress);return {mode:state.mode,budget:budgetSummary(state.home,state.budget),home:affordability(h),income:requiredIncome(h),netWorth:netWorth(state.worth),projection:projectPlan(state).end}}},
 {name:'configure_home_plan',title:'Update household plan',description:'Update specified home worksheet fields and refresh visible results. Does not save a scenario or transmit data.',inputSchema:{type:'object',properties:{fields:{type:'object',properties:Object.fromEntries(Object.keys(LABELS).map(k=>[k,{type:'number',minimum:homeLimits(k)[0],maximum:homeLimits(k)[1]}])),additionalProperties:false}},required:['fields'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='fields')||!input.fields||Array.isArray(input.fields)||typeof input.fields!=='object'||Object.keys(input.fields).some(k=>!Object.hasOwn(LABELS,k)))throw new Error('Unknown household field.');const next={...state.home,...input.fields};const errors=validateHome(next);if(errors.length)throw new Error(errors.join(' '));const target=state.home.age+state.worth.years;state.home=next;for(const key of Object.keys(input.fields))markEntered(state,'home',key);state.worth.years=projectionYears(next.age,Math.min(120,next.age+100,Math.max(next.age+1,target)));render();return {updated:Object.keys(input.fields),home:affordability(applyStress(state.home,state.stress))}}},
 {name:'set_projection_years',title:'Set forecast horizon',description:'Set a horizon of 1–100 years, ending no later than age 120, and open the future net worth worksheet. Does not save or transmit data.',inputSchema:{type:'object',properties:{years:{type:'integer',minimum:1,maximum:100}},required:['years'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='years')||!Number.isInteger(input.years)||input.years<1||input.years>100)throw new Error('Enter a whole number from 1 to 100.');projectionYears(state.home.age,state.home.age+input.years);state.worth.years=input.years;state.mode='worth';state.worthView='future';render();return projectPlan(state).end}}
 ];for(const t of tools){try{Promise.resolve(context.registerTool(t)).catch(()=>{})}catch{}}
}
registerTools(document.modelContext);

// Annual entry changes presentation only; the shared stored value remains monthly.
document.addEventListener('change',async e=>{
 if(e.target.matches('[data-period]')){const key=e.target.dataset.period;if(invalid.size){notice('Correct this amount before changing its period.');e.target.value=state.budget.annualFields.includes(key)?'annual':'monthly';return}state.budget.annualFields=state.budget.annualFields.filter(k=>k!==key);if(e.target.value==='annual')state.budget.annualFields.push(key);const opens=$$('.fold[open]').map(el=>el.id);render();opens.forEach(id=>{if($('#'+id))$('#'+id).open=true});$('[data-period="'+key+'"]').focus()}
 if(e.target.id==='summary-file'){const file=e.target.files[0];if(!file)return;if(issues().length){notice('Correct highlighted inputs before importing. Your draft has not been changed.');e.target.value='';return;}try{if(file.size>2000000)throw Error('Choose a CSV smaller than 2 MB.');const updates=reviewSummary(await file.text(),state.home);dialog('Review imported amounts',miniNote('These fields will replace current entries across the site. Unlisted fields stay as entered. Values below use the site’s normal annual-income and monthly-expense units.')+'<div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable financial figures"><table><thead><tr><th>Field</th><th>Current</th><th>Imported</th></tr></thead><tbody>'+updates.map(x=>'<tr><th>'+esc(x.key==='currentHousing'?'Current housing / month':LABELS[x.key])+'</th><td>'+money(x.key==='currentHousing'?state.budget.currentHousing:x.before)+'</td><td>'+money(x.value)+'</td></tr>').join('')+'</tbody></table></div><div class="dialog-actions"><button class="btn" data-close>Cancel</button><button class="btn dark" id="apply-summary">Apply reviewed amounts</button></div>',d=>$('#apply-summary').onclick=()=>{if(issues().length){notice('Correct highlighted inputs before applying an import.');return;}for(const x of updates){if(x.key==='currentHousing'){state.budget.currentHousing=x.value;markEntered(state,'budget',x.key,'imported')}else{state.home[x.key]=x.value;markEntered(state,'home',x.key,'imported')}}d.close();render();notice('Reviewed amounts applied. Save a scenario to keep them on this device.');});}catch(err){notice(err.message)}e.target.value='';}
});
document.addEventListener('click',e=>{if(e.target.closest('#download-summary-template')){const url=URL.createObjectURL(new Blob([summaryTemplate()],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='daves-dollars-summary-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
